function canStopAt(maze: number[][], start: number[], target: number[]): boolean {
  const m = maze.length, n = maze[0].length;
  const seen = maze.map(row => row.map(() => false));
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const stack = [start];
  seen[start[0]][start[1]] = true;
  while (stack.length) {
    const [r, c] = stack.pop()!;
    if (r === target[0] && c === target[1]) return true;
    for (const [dr, dc] of dirs) {
      let i = r, j = c;
      while (i + dr >= 0 && i + dr < m && j + dc >= 0 && j + dc < n && maze[i + dr][j + dc] === 0) { i += dr; j += dc; }
      if (!seen[i][j]) { seen[i][j] = true; stack.push([i, j]); }
    }
  }
  return false;
}

