    def canStopAt(self, maze: List[List[int]], start: List[int], target: List[int]) -> bool:
        m, n = len(maze), len(maze[0])
        seen = {tuple(start)}
        stack = [tuple(start)]
        while stack:
            r, c = stack.pop()
            if [r, c] == target:
                return True
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                i, j = r, c
                while 0 <= i + dr < m and 0 <= j + dc < n and maze[i + dr][j + dc] == 0:
                    i += dr
                    j += dc
                if (i, j) not in seen:
                    seen.add((i, j))
                    stack.append((i, j))
        return False

