function canStopAt(maze: number[][], start: number[], target: number[]): boolean {
  const m = maze.length, n = maze[0].length;
  const seen = new Uint8Array(m * n);
  const queue: number[] = [start[0] * n + start[1]];
  seen[queue[0]] = 1;
  for (let head = 0; head < queue.length; head++) {
    const r = Math.floor(queue[head] / n), c = queue[head] % n;
    if (r === target[0] && c === target[1]) return true;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      let i = r, j = c;
      while (i + dr >= 0 && i + dr < m && j + dc >= 0 && j + dc < n && maze[i + dr][j + dc] === 0) { i += dr; j += dc; }
      const key = i * n + j;
      if (!seen[key]) { seen[key] = 1; queue.push(key); }
    }
  }
  return false;
}

